#simple calculator app. generated by Claude.
#hand typed by me.

import tkinter as tk

#colors and fonts
BG = "#1e1f26"
DISPLAY_FG = "#ffffff"
HINT_FG = "#8b8fa3"
NUM_BG = "#2d2f3a"
NUM_HOVER = "#3a3d4c"
OP_BG = "#ff9f43"
OP_HOVER = "#ffb56b"
FN_BG = "#44475a"
FN_HOVER = "#565a70"

BTN_FONT = ("Helvetica", 18)
DISPLAY_FONT = ("Helvetica", 36)
HINT_FONT = ("Helvetica", 12)

#operator symbol to function mapping
OPERATIONS = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "x": lambda a, b: a * b,
    "÷": lambda a, b: a / b,
}

#keyboard keys trigger operator symbols
KEY_TO_OPERATOR = {"+": "+", "-": "-", "*": "x", "/": "÷"}

class Calculator(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Calculator")
        self.configure(bg=BG, padx=12, pady=12)
        self.resizable(False, False)

        #calculator state
        self.current = "0"
        self.stored = None
        self.operator = None
        self.reset_next = False

        self._build_display()
        self._build_buttons()
        self.bind("<Key>", self._on_key)

    #ui construction
    def _build_display(self):
        self.hint_var = tk.StringVar(value="")
        self.display_var = tk.StringVar(value=self.current)

        tk.Label(self, textvariable=self.hint_var, font=HINT_FONT,
                bg=BG, fg=HINT_FG, anchor="e").grid(row=0, column=0, columnspan=4, sticky="ew")
        tk.Label(self, textvariable=self.display_var, font=DISPLAY_FONT,
                bg=BG, fg=DISPLAY_FG, anchor="e").grid(row=1, column=0, columnspan=4, sticky="ew", pady=(0,10))

    def _build_buttons(self):
                #label, row, column, rowspan, colspan, kind, command)
        layout = [
            ("C", 2, 0, 1, 1, "fn", self.clear),
            ("⌫", 2, 1, 1, 1, "fn", self.backspace),
            ("÷", 2, 2, 1, 1, "op", lambda: self.press_operator("÷")),
            ("x", 2, 3, 1, 1, "op", lambda: self.press_operator("x")),

            ("7", 3, 0, 1, 1, "num", lambda: self.press_digit("7")),
            ("8", 3, 1, 1, 1, "num", lambda: self.press_digit("8")),
            ("9", 3, 2, 1, 1, "num", lambda: self.press_digit("9")),
            ("-", 3, 3, 1, 1, "op", lambda: self.press_operator("-")),

            ("4", 4, 0, 1, 1, "num", lambda: self.press_digit("4")),
            ("5", 4, 1, 1, 1, "num", lambda: self.press_digit("5")),
            ("6", 4, 2, 1, 1, "num", lambda: self.press_digit("6")),
            ("+", 4, 3, 1, 1, "op", lambda: self.press_operator("+")),

            ("1", 5, 0, 1, 1, "num", lambda: self.press_digit("1")),
            ("2", 5, 1, 1, 1, "num", lambda: self.press_digit("2")),
            ("3", 5, 2, 1, 1, "num", lambda: self.press_digit("3")),
            ("=", 5, 3, 2, 1, "op", self.calculate),

            ("0", 6, 0, 1, 2, "num", lambda: self.press_digit("0")),
            (".", 6, 2, 1, 1, "num", self.press_dot),
        ]

        colors = {"num": (NUM_BG, NUM_HOVER), "op": (OP_BG, OP_HOVER), "fn": (FN_BG, FN_HOVER)}

        for text, row, col, rowspan, colspan, kind, command in layout:
            bg, hover = colors[kind]
            btn = tk.Label(self, text=text, font=BTN_FONT, bg=bg, fg="white",
                            width=4 * colspan, height=2 * rowspan, cursor="hand2")
            btn.grid(row=row, column=col, rowspan=rowspan, columnspan=colspan,
                    padx=3, pady=3, sticky="nsew")
            btn.bind("<Button-1>", lambda e, cmd=command: cmd())
            btn.bind("<Enter>", lambda e, b=btn, h=hover: b.config(bg=h))
            btn.bind("<Leave>", lambda e, b=btn, c=bg: b.config(bg=c))

        #calculator logic
    def _update_display(self):
        self.display_var.set(self.current)

    def _format(self, value):
        return f"{value:.10g}"

    def press_digit(self, digit):
        if self.reset_next or self.current in ("0", "Error"):
            self.current = digit
            self.reset_next = False
        else:
            self.current += digit
        self._update_display()

    def press_dot(self):
        if self.reset_next or self.current == "Error":
            self.current = "0."
            self.reset_next = False
        elif "." not in self.current:
            self.current += "."
        self._update_display()

    def press_operator(self, op):
        if self.current == "Error":
            return
        if self.operator and not self.reset_next:
            self.calculate()
            if self.current == "Error":
                return
        self.stored = float(self.current)
        self.operator = op
        self.reset_next = True
        self.hint_var.set(f"{self._format(self.stored)} {op}") 

    def calculate(self):
        if self.operator is None or self.stored is None or self.reset_next:
            return
        second = float(self.current)
        try: 
            result = OPERATIONS[self.operator](self.stored, second)
            self.hint_var.set(f"{self._format(self.stored)} {self.operator}"
                                f"{self._format(second)} =")
            self.current = self._format(result)
        except ZeroDivisionError:
            self.hint_var.set("")
            self.current = "Error"

        self.stored = None
        self.operator = None
        self.reset_next = True
        self._update_display()

    def clear(self):
        self.current = "0"
        self.stored = None
        self.operator = None
        self.reset_next = False
        self.hint_var.set("")
        self._update_display()

    def backspace(self):
        if self.reset_next or self.current == "Error":
            return
        self.current = self.current[:-1] or "0"
        self._update_display()

    #keyboard support
    def _on_key(self, event):
        key = event.char
        if key.isdigit():
            self.press_digit(key)
        elif key == ".":
            self.press_dot()
        elif key in KEY_TO_OPERATOR:
            self.press_operator(KEY_TO_OPERATOR[key])
        elif key in ("=", "\r"):
            self.calculate()
        elif event.keysym == "BackSpace":
            self.backspace()
        elif event.keysym == "Escape" or key.lower() == "c":
            self.clear()

if __name__ == "__main__":
    Calculator().mainloop()
            
